// franchise booked and is what the summary counts; DESTINATION matches what it
// must deliver; ANY is both, for a franchise that wants its whole workload.
func (q *Queries) PortalFranchiseShipments(ctx context.Context, arg PortalFranchiseShipmentsParams) ([]PortalFranchiseShipmentsRow, error) {
	rows, err := q.db.Query(ctx, portalFranchiseShipments,
		arg.OrganizationID,
		arg.UnitID,
		arg.Role,
		arg.Status,
		arg.CursorID,
		arg.RowLimit,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []PortalFranchiseShipmentsRow{}
	for rows.Next() {
		var i PortalFranchiseShipmentsRow
		if err := rows.Scan(
			&i.PublicID,
			&i.Awb,
			&i.CurrentStatus,
			&i.PieceCount,
			&i.DestinationPincode,
			&i.PaymentMode,
			&i.TotalAmountMinor,
			&i.CodAmountMinor,
			&i.Currency,
			&i.BookedAt,
			&i.CreatedAt,
			&i.ID,
			&i.CustomerName,
			&i.ServiceCode,
			&i.FranchiseRole,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const portalFranchiseSummary = `-- name: PortalFranchiseSummary :one

SELECT
    COALESCE(SUM(booked_count), 0)::bigint    AS booked,
    COALESCE(SUM(delivered_count), 0)::bigint AS delivered,
    COALESCE(SUM(ndr_count), 0)::bigint       AS ndr,
    COALESCE(SUM(rto_count), 0)::bigint       AS rto,
    COALESCE(SUM(revenue_minor), 0)::bigint   AS revenue_minor,
    COALESCE(SUM(cod_amount_minor), 0)::bigint AS cod_booked_minor
FROM shipment_daily_stats
WHERE organization_id = $1
  AND operating_unit_id = ANY($2::bigint[])
  AND stat_date BETWEEN $3 AND $4
`

type PortalFranchiseSummaryParams struct {
	OrganizationID int64
	UnitIds        []int64
	FromDate       time.Time
	ToDate         time.Time
}

type PortalFranchiseSummaryRow struct {
	Booked         int64
	Delivered      int64
	Ndr            int64
	Rto            int64
	RevenueMinor   int64
	CodBookedMinor int64
}

// ---------------------------------------------------------------------------
// M28 Franchise portal
// ---------------------------------------------------------------------------
// What the franchise booked and delivered in a period, read from the rollup
// rather than from shipments.
func (q *Queries) PortalFranchiseSummary(ctx context.Context, arg PortalFranchiseSummaryParams) (PortalFranchiseSummaryRow, error) {
	row := q.db.QueryRow(ctx, portalFranchiseSummary,
		arg.OrganizationID,
		arg.UnitIds,
		arg.FromDate,
		arg.ToDate,
	)
	var i PortalFranchiseSummaryRow
	err := row.Scan(
		&i.Booked,
		&i.Delivered,
		&i.Ndr,
		&i.Rto,
		&i.RevenueMinor,
		&i.CodBookedMinor,
	)
	return i, err
}
